using System;using System.Collections.Generic;using System.Linq;using System.Threading.Tasks;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using accounts-management.Data;using accounts-management.Models;namespace accounts-management.Services{public class AccountService:IAccountService{private readonly ApplicationDbContext _db;private readonly ILogger<AccountService> _logger;public AccountService(ApplicationDbContext db,ILogger<AccountService> logger){_db=db;_logger=logger;}public async Task<IEnumerable<Account>> GetAllAsync(){return await _db.Accounts.AsNoTracking().OrderBy(a=>a.Id).ToListAsync();}public async Task<Account?> GetByIdAsync(long id){return await _db.Accounts.AsNoTracking().FirstOrDefaultAsync(a=>a.Id==id);}public async Task<IReadOnlyList<Account>> CreateManyAsync(IEnumerable<AccountCreateDto> dtos){var list=dtos?.ToList()??new List<AccountCreateDto>();if(list.Count==0)throw new ArgumentException("No accounts provided");if(list.Any(d=>string.IsNullOrWhiteSpace(d.Name)||string.IsNullOrWhiteSpace(d.Email)))throw new ArgumentException("Name and Email are required for all accounts");var inputEmails=list.Select(x=>x.Email.Trim().ToLowerInvariant()).ToList();if(inputEmails.Count!=inputEmails.Distinct().Count())throw new ArgumentException("Duplicate emails found in request payload");var entities=list.Select(d=>new Account{Name=d.Name.Trim(),Email=d.Email.Trim(),Address=string.IsNullOrWhiteSpace(d.Address)?null:d.Address!.Trim()}).ToList();using var tx=await _db.Database.BeginTransactionAsync();try{await _db.Accounts.AddRangeAsync(entities);await _db.SaveChangesAsync();await tx.CommitAsync();_logger.LogInformation("Created {Count} accounts",entities.Count);return entities;}catch(DbUpdateException ex){await tx.RollbackAsync();_logger.LogError(ex,"Database update error during bulk create");throw new ArgumentException("One or more accounts could not be created (possible duplicate email)");}}public async Task<Account?> UpdateAsync(long id,AccountUpdateDto dto){var entity=await _db.Accounts.FirstOrDefaultAsync(a=>a.Id==id);if(entity==null)return null;entity.Name=dto.Name.Trim();entity.Email=dto.Email.Trim();entity.Address=string.IsNullOrWhiteSpace(dto.Address)?null:dto.Address!.Trim();try{await _db.SaveChangesAsync();_logger.LogInformation("Updated account {Id}",id);return entity;}catch(DbUpdateException ex){_logger.LogError(ex,"Database update error during update {Id}",id);throw new ArgumentException("Update failed (possible duplicate email)");}}public async Task<bool> DeleteAsync(long id){var entity=await _db.Accounts.FirstOrDefaultAsync(a=>a.Id==id);if(entity==null)return false;_db.Accounts.Remove(entity);await _db.SaveChangesAsync();_logger.LogInformation("Deleted account {Id}",id);return true;}}}